enum fuzz_field_kind {
	FUZZ_FIELD_INT = 0,
	FUZZ_FIELD_OPAQUE = 1,
};

struct fuzz_field {
	const char *name;
	enum fuzz_frame_type frame;
	/* Management subtype this field belongs to, or -1 for a
	 * frame kind that has only one layout. */
	int stype;
	unsigned int offset;
	unsigned int width;
	enum fuzz_field_kind kind;
	/* 1 when the field reads most significant octet first.
	 * Does not change what the sweep covers; it changes what
	 * a given case VALUE means, and so whether the ladder's
	 * edges are the field's edges. */
	int big_endian;
};

